using System;
using Sandbox;

namespace Survival;

/// <summary>
/// One-handed sword presentation on the sword build of the human graph
/// (<c>models/player/human_male_sword.vmdl</c> → <c>human_sword.vanmgrph</c>, generated by
/// <c>Tools/make_human_sword_assets.py</c>; clips authored in <c>Blender/scripts/create_sword_anims.py</c>).
/// Two phases: the graph's <c>sword_pose</c> selector holds the weapon by the waist whatever side the cursor aims
/// (Mark 2026-11-17: "the players 'weapon equipped but idle' position has the weapon by their waist ... When we change
/// from left right overhead dont change the pose or position of the weapon, that only happens when we actually initiate
/// an attack"); a click switches it to the aimed side's wind-up clip (waist → wind → cocked), whose playhead is
/// <c>sword_wind</c> = the windup's progress, so the weapon keeps drawing up through the whole windup and is fully cocked
/// as the strike fires (Mark 2026-11-16: "the windup should be moving through the whole thing, right now its just
/// snapping to poses mostly"); a click out of a strike's follow-through or the guard starts the draw on the wind frame
/// (<see cref="WindUpStartOutOfStrike"/>). A held heavy hangs at the cocked frame; morphed across the face it passes the
/// swap pose (sword up in front). When the host's
/// damage window opens <c>b_attack</c> plays the strike clip picked by <c>sword_attack</c> — every strike clip starts
/// on its cocked frame and sweeps the path over 0.30 s (slower than the 0.18 s damage window: "slower strike phase",
/// the combat timings stay), then settles back to rest. A new
/// click sets <c>b_sword_interrupt</c> (0.12 s cut into the next cocked pose) and a raised guard sets
/// <c>b_sword_guard</c>, which both cuts a settling strike and switches the graph's guard selector to the
/// guard pose in 0.15 s (at a steady rate, the same as moving a held guard, 2026-11-17); <c>sword_guard_dir</c> (= the guard's <see cref="SwingDirs"/>: Sword_Block_L / _R / _Up) picks
/// left / right / overhead and cross-fades while the held guard moves (Mark 2026-11-14) — the guard is not a
/// <c>sword_pose</c> value, so the rest / cock / morph blends keep their own 0.125 s. Remote peers get the cocked pose
/// and strike (host swing broadcast) on the same timeline.
/// </summary>
public sealed partial class PlayerAnimation
{
	[Property, Group( "Animation" ), Title( "Strike clip length (s)" ), Description( "Wall-clock length of the authored strike clips (Sword_Attack_*: cocked → 0.30 s swoop → follow-through held → settle → rest, create_sword_anims.py STRIKE_END). A follow-up click or a block interrupts the follow-through." ), Range( 0.2f, 1.5f ), Step( 0.01f )]
	public float MeleeStrikeClipSeconds { get; set; } = StrikeClipLengthSeconds;

	/// <summary>The authored strike clips' length (create_sword_anims.py STRIKE_END); scavs present on it too (<see cref="EntityCombat"/>).</summary>
	public const float StrikeClipLengthSeconds = 0.64f;

	/// <summary>Clip share of the wind frame (create_sword_anims.py WIND_AT_S / WIND_END_S): a draw out of a strike or the guard starts there.</summary>
	public const float WindFrameShare = 0.5f;

	/// <summary>Graph <c>sword_pose</c> values: children of the pose selector (make_human_sword_assets.py POSE_CLIPS order; EntityCombat mirrors them).</summary>
	internal static class SwordPose
	{
		public const int CockedL = 0;
		public const int Rest = 1;
		public const int CockedR = 2;
		public const int CockedOver = 3;
		public const int SwapMid = 4;
	}

	/// <summary>
	/// A held heavy morphed across the face (right / overhead ↔ left) stops up in front (Sword_Swap_Mid) this long before
	/// the other side's cocked pose; the graph cross-fades 0.125 s into and out of it.
	/// </summary>
	[Property, Group( "Animation" ), Title( "Morph across the face: hold in front (s)" ), Description( "A held heavy morphed between the left and the right / overhead sides passes up in front of the face this long." ), Range( 0.05f, 0.5f ), Step( 0.005f )]
	public float SwordSwapMidSeconds { get; set; } = 0.125f;

	/// <summary>
	/// Where the wind-up draw starts when the click comes out of a strike's follow-through or the guard (share of the
	/// clip: create_sword_anims.py WIND_AT_S / WIND_END_S = the wind frame), so a chained swing never dips back to the waist.
	/// </summary>
	[Property, Group( "Animation" ), Title( "Wind-up start out of a strike / guard (0-1)" ), Range( 0f, 0.9f ), Step( 0.05f )]
	public float WindUpStartOutOfStrike { get; set; } = WindFrameShare;

	/// <summary>A heavy morph across the face (left ↔ right / overhead) goes up in front first.</summary>
	bool _cockViaMid;
	double _cockMidUntil;

	/// <summary>Graph <c>sword_attack</c> values: children of the strike selector.</summary>
	static class SwordAttack
	{
		public const int R = 0;
		public const int L = 1;
		public const int Over = 2;
	}

	/// <summary>The cocked pose is applied and the strike has not fired yet (click → windup).</summary>
	bool _swordCocked;
	/// <summary>A strike is scheduled (release / host start) — the swing is committed.</summary>
	bool _swordStrikeScheduled;
	bool _swordStrikeStarted;
	double _swordStrikeAtSandbox;
	byte _swordAttackType;

	/// <summary>
	/// The wind-up pose is on this body on this machine and its strike has not started (any peer): what an opponent
	/// reads, and what the incoming-attack marker reads (<see cref="PlayerCombat.TryGetIncomingAttackSide"/>).
	/// </summary>
	public bool TryGetShownSwordWindup( out byte attackType )
	{
		attackType = _swordAttackType;
		return _swordCocked && !_swordStrikeStarted;
	}

	bool _appliedSwordInterrupt;
	bool _appliedSwordGuard;
	bool _ownerSkipNextRemoteSwingApply;
	int _appliedSwordPose = -1;
	int _appliedSwordAttack = -1;
	int _appliedSwordGuardDir = -1;

	/// <summary>The wind-up draw: sword_wind runs 0 → 1 from <see cref="_windStartAt"/> to <see cref="_windEndAt"/> and never goes back.</summary>
	double _windStartAt;
	double _windEndAt;
	float _windFrom;
	float _windShown;
	float _appliedSwordWind = -1f;

	/// <summary>Cocked pose on and no strike scheduled yet.</summary>
	public bool IsMeleeSwingSnapActive => _swordCocked && !_swordStrikeScheduled;

	/// <summary>
	/// Single gate for "a committed strike is playing": from the strike being scheduled through the clip's
	/// return to rest. Purely time-bounded so it can never latch busy forever. Both the next attack and the
	/// arc overlay are bound to this. The press cocked pose is deliberately excluded — the attack being
	/// aimed must still be allowed to fire.
	/// </summary>
	public bool IsMeleeSwingAnimBusy => GetMeleeAttackAnimBusyRemainingSeconds() > 0.01f;

	/// <summary>The strike clip (the damage swoop and its settle) is playing - not the cocked windup / held heavy.</summary>
	public bool IsMeleeStrikePresenting => _swordStrikeStarted && IsMeleeSwingAnimBusy;

	/// <summary>True while a cocked pose or a committed strike owns the sword arm.</summary>
	public bool HasActiveMeleeSwingPresentation => _swordCocked || IsMeleeSwingAnimBusy;

	static int CockedPoseFor( byte attackType ) => attackType switch
	{
		MeleeAttackTypes.Left => SwordPose.CockedL,
		MeleeAttackTypes.Forward => SwordPose.CockedOver,
		_ => SwordPose.CockedR
	};

	static int StrikeFor( byte attackType ) => attackType switch
	{
		MeleeAttackTypes.Left => SwordAttack.L,
		MeleeAttackTypes.Forward => SwordAttack.Over,
		_ => SwordAttack.R
	};

	/// <summary>A left wind-up sits on the other side of the face from a right / overhead one.</summary>
	static bool CocksOnLeft( byte attackType ) => attackType == MeleeAttackTypes.Left;

	/// <summary>The draw starts at the waist from the idle carry; out of a strike still settling or the guard it starts on the wind frame.</summary>
	float WindUpStartProgress() => _swordStrikeStarted || _appliedSwordGuard ? Math.Clamp( WindUpStartOutOfStrike, 0f, 0.9f ) : 0f;

	float StrikePresentationSeconds() => Math.Max( 0.2f, MeleeStrikeClipSeconds );

	/// <summary>Share of the strike clip after which the pose under it is the waist rest (the clip's settle: create_sword_anims.py FOLLOW_HOLD 0.47 of 0.64, less the 0.125 s selector blend).</summary>
	const float StrikeRestFromShare = 0.7f;

	/// <summary>Owner click: cocked pose now (a strike still settling is cut short), held until the strike fires.</summary>
	public void BeginMeleeSwingSnap( byte attackType )
	{
		if ( !PlayMeleeSwingAnimation || !GameObject.IsValid() )
			return;

		if ( _swordCocked && !_swordStrikeScheduled )
		{
			_swordAttackType = attackType;
			return;
		}

		var drawFrom = WindUpStartProgress();
		_swordCocked = true;
		_swordStrikeScheduled = false;
		_swordStrikeStarted = false;
		_swordStrikeAtSandbox = double.MaxValue;
		_swordAttackType = attackType;
		_cockViaMid = false;
		_meleeAttackAnimBusyUntilSandbox = 0;
		// The draw runs over the class windup until the strike is scheduled with the real one.
		StartWindUp( Time.NowDouble, Time.NowDouble + ClassWindupSeconds(), drawFrom );
		ApplyHoldPose( HoldPose.MeleeTwoHand );

		Components.Get<PlayerCombat>()?.LogMeleeAnimStart(
			"graph cocked pose (held)",
			$"type={MeleeAttackTypes.Label( attackType )} sword_pose={CockedPoseFor( attackType )}" );
	}

	/// <summary>
	/// Owner click: commit the strike. The cocked pose holds for the predicted windup, then the strike clip
	/// fires. The host re-schedules with its authoritative windup when it accepts the swing.
	/// </summary>
	public void ReleaseMeleeSwingSnap( byte attackType, float windupRemainingSeconds )
	{
		if ( !PlayMeleeSwingAnimation || !GameObject.IsValid() )
			return;

		_ownerSkipNextRemoteSwingApply = true;
		ScheduleMeleeStrike( attackType, windupRemainingSeconds, "owner click" );
	}

	/// <summary>Owner heavy: the button came up — move the pending strike there (never earlier than the heavy windup).</summary>
	internal void RescheduleOwnerStrike( double strikeAtSandbox )
	{
		if ( !_swordCocked || !_swordStrikeScheduled || _swordStrikeStarted )
			return;

		_swordStrikeAtSandbox = strikeAtSandbox;
		_meleeAttackAnimBusyUntilSandbox = strikeAtSandbox + StrikePresentationSeconds();
	}

	/// <summary>
	/// Heavy morph: the held cocked pose moves to <paramref name="attackType"/>'s side (through the swap pose when it
	/// crosses the face) and the strike will play that side's clip. Nothing once the strike started.
	/// </summary>
	internal void MorphCockedSwing( byte attackType )
	{
		if ( !_swordCocked || _swordStrikeStarted || _swordAttackType == attackType )
			return;

		var crosses = CocksOnLeft( attackType ) != CocksOnLeft( _swordAttackType );
		_swordAttackType = attackType;
		_cockViaMid = crosses;
		_cockMidUntil = Time.NowDouble + Math.Max( 0.04f, SwordSwapMidSeconds );
		Components.Get<PlayerCombat>()?.LogMeleeAnimStart( "graph cocked pose (heavy morph)",
			$"type={MeleeAttackTypes.Label( attackType )} sword_pose={CockedPoseFor( attackType )}" );
	}

	/// <summary>Drop the cocked pose / pending strike (block, shove, hit reaction).</summary>
	public void CancelMeleeSwingSnap()
	{
		if ( !_swordCocked && !_swordStrikeScheduled )
			return;

		EndMeleeSwing( "cancel" );
	}

	/// <summary>
	/// Host / local swing commit with the authoritative remaining windup. Cocks first when nothing is on
	/// screen (remote peers, host pawn without a press), then schedules the strike.
	/// </summary>
	/// <summary>
	/// <see cref="PlayMeleeSwingAttack"/> windup value meaning "cock now, strike when the host's strike cue arrives".
	/// Everyone but the pawn's own driver presents swings this way, so a light that is held into a heavy never
	/// shows a strike at the light time.
	/// </summary>
	public const float StrikeOnCue = -1f;

	/// <summary>
	/// "Strike on the host's cue" that still tells the peer how long the windup should take, so its wind-up draw can run
	/// over it: -(1 + windup). Every value below zero means on cue; <see cref="WindupFromCue"/> reads the windup back.
	/// </summary>
	public static float StrikeOnCueAfter( float windupSeconds ) => -(1f + Math.Max( 0f, windupSeconds ));

	/// <summary>The windup a <see cref="StrikeOnCueAfter"/> value carries (0 for the bare <see cref="StrikeOnCue"/>).</summary>
	static float WindupFromCue( float value ) => value < 0f ? Math.Max( 0f, -value - 1f ) : value;

	/// <summary>How long a cocked pose waits for a strike cue that never comes (lost packet) before it lets go.</summary>
	const float StrikeCueTimeoutSeconds = 2f;

	/// <param name="windupRemainingSeconds">Seconds until the strike on this machine, or <see cref="StrikeOnCue"/>.</param>
	/// <param name="applyLocally">False: only broadcast (the host's own driven pawn already predicted the swing).</param>
	public void PlayMeleeSwingAttack( byte attackType, bool broadcastFromHost, float windupRemainingSeconds, bool applyLocally = true )
	{
		if ( !PlayMeleeSwingAnimation || !GameObject.IsValid() )
			return;

		if ( applyLocally )
			ScheduleMeleeStrike( attackType, windupRemainingSeconds, windupRemainingSeconds < 0f ? "host swing start (strike on cue)" : "host strike" );

		if ( !broadcastFromHost )
			return;

		// Remote peers never get the light windup: a swing start cocks and draws over the windup, the host's cue (0)
		// strikes.
		windupRemainingSeconds = windupRemainingSeconds > 0f ? StrikeOnCueAfter( windupRemainingSeconds ) : windupRemainingSeconds;

		if ( GameObject.Network is not { Active: true } || !Networking.IsHost )
			return;

		NetworkedHoldPose = (byte)HoldPose.MeleeTwoHand;
		NetworkedSwingAttackType = attackType;
		NetworkedSwingWindupRemainingSeconds = windupRemainingSeconds;
		NetworkedSwingCounter++;

		_deferredSwingAnimType = attackType;
		_deferredSwingAnimWindupRemaining = windupRemainingSeconds;
		_deferSwingAnimBroadcast = true;
	}

	void ScheduleMeleeStrike( byte attackType, float windupRemainingSeconds, string source )
	{
		ApplyHoldPose( HoldPose.MeleeTwoHand );

		// A strike that already fired is the PREVIOUS swing still settling: this is the next swing (a
		// follow-up click fires the moment the damage swoop ends), so it re-cocks and schedules fresh.
		var drawing = _swordCocked && !_swordStrikeStarted;
		var drawFrom = WindUpStartProgress();
		if ( !drawing )
			_cockViaMid = false;
		_swordStrikeStarted = false;
		var onCue = windupRemainingSeconds < 0f;
		var remaining = Math.Max( 0f, windupRemainingSeconds );
		_swordCocked = true;
		_swordAttackType = attackType;
		_swordStrikeScheduled = true;
		_swordStrikeAtSandbox = onCue ? double.MaxValue : Time.NowDouble + remaining;
		// The draw ends where the strike fires: on time, or after the windup a cue carries (else the class windup).
		var now = Time.NowDouble;
		var cueWindup = WindupFromCue( windupRemainingSeconds );
		var drawEnd = onCue ? now + (cueWindup > 0f ? cueWindup : ClassWindupSeconds()) : _swordStrikeAtSandbox;
		if ( drawing )
			_windEndAt = drawEnd;   // the press already started the draw: only its end moves
		else
			StartWindUp( now, drawEnd, drawFrom );
		_meleeAttackAnimBusyUntilSandbox = onCue
			? Time.NowDouble + StrikeCueTimeoutSeconds
			: _swordStrikeAtSandbox + StrikePresentationSeconds();

		Components.Get<PlayerCombat>()?.LogMeleeAnimStart(
			"graph strike scheduled",
			$"{source} type={MeleeAttackTypes.Label( attackType )} in={remaining:0.###}s busy={GetMeleeAttackAnimBusyRemainingSeconds():0.###}s" );
	}

	/// <summary>Per frame: rest side, cocked pose, fire the strike on time, restore the rate when the clip is done.</summary>
	void TickMeleeSwing()
	{
		var body = ResolveBody();
		if ( body is null || !body.IsValid() )
			return;

		var meleeHold = ResolvePresentationHoldPose() == HoldPose.MeleeTwoHand && !_combatSequenceActive
		                && !_hitReactionPoseActive && !_ledgeMantlePoseActive;
		var now = Time.NowDouble;

		// The driving owner is still holding the button as the light strike comes due: it turns heavy, and the
		// cocked pose keeps hanging to the heavy windup (PlayerCombat decides; the host confirms the same way).
		if ( _swordCocked && _swordStrikeScheduled && !_swordStrikeStarted && now >= _swordStrikeAtSandbox
		     && ResolveCombat() is { IsValid: true } heavyCheck && heavyCheck.TryExtendOwnerSwingToHeavy( out var heavyAt )
		     && heavyAt > now )
		{
			_swordStrikeAtSandbox = heavyAt;
			_meleeAttackAnimBusyUntilSandbox = heavyAt + StrikePresentationSeconds();
		}

		if ( _swordCocked && _swordStrikeScheduled && !_swordStrikeStarted && now >= _swordStrikeAtSandbox )
		{
			_swordStrikeStarted = true;
			_swordCocked = false;
			_cockViaMid = false;
			// The slash ribbon's replay on this machine starts with the strike it shows.
			ResolveCombat()?.OnSwingStrikeShown( _swordAttackType );
			if ( meleeHold )
			{
				SetSwordInterruptParam( body, false );
				SetSwordGuardParam( body, false );
				SetSwordAttackParam( body, StrikeFor( _swordAttackType ) );
				body.Set( "b_attack", true );
			}

			Components.Get<PlayerCombat>()?.LogMeleeAnimStart(
				"graph STRIKE (b_attack)",
				$"type={MeleeAttackTypes.Label( _swordAttackType )} sword_attack={StrikeFor( _swordAttackType )}" );
		}

		// A heavy held on the host keeps the remote cocked pose up however long it hangs (no max charge since 2026-11-16).
		if ( !_swordStrikeStarted && _swordStrikeScheduled && _swordStrikeAtSandbox == double.MaxValue
		     && ResolveCombat() is { IsValid: true, HeavyHoldShown: true } holder && !holder.IsLocalCombatDriver() )
			_meleeAttackAnimBusyUntilSandbox = now + StrikeCueTimeoutSeconds;

		if ( _swordStrikeStarted && now >= _meleeAttackAnimBusyUntilSandbox )
			EndMeleeSwing( "strike clip done" );
		else if ( !_swordStrikeStarted && _swordStrikeScheduled && _swordStrikeAtSandbox == double.MaxValue
		          && now >= _meleeAttackAnimBusyUntilSandbox )
			EndMeleeSwing( "strike cue never came" );

		if ( !meleeHold )
			return;

		if ( _swordCocked && !_swordStrikeStarted )
			SetSwordWindParam( body, WindUpProgress( now ) );

		// A cocked pose waiting for its strike, or a raised guard, cuts a settling strike clip short.
		var guard = IsGuardStanceShown();
		SetSwordGuardParam( body, guard );
		// Guard down: the side selector already sits where a press would raise it, so the guard never rises on the last
		// guard's side and then cross-fades over (the doubled-up blend when the mouse moved before the click).
		if ( ResolveCombat() is { IsValid: true } guardCombat )
			SetSwordGuardDirParam( body, guard ? guardCombat.GetActiveBlockDirection() : guardCombat.GetPendingBlockDirection() );
		SetSwordInterruptParam( body, !guard && _swordCocked && !_swordStrikeStarted );
		SetSwordPoseParam( body, ResolveSwordPose( now ) );
	}

	/// <summary>
	/// The aimed side's wind-up while a press / pending strike holds it (up in front first after a heavy morph across the
	/// face); otherwise the waist carry, whatever side the cursor aims. Under a raised guard (b_sword_guard shows the
	/// block pose over this selector) the rest just holds.
	/// </summary>
	int ResolveSwordPose( double now )
	{
		// Under a strike the selector keeps the strike's cocked pose (its wind-up clip stays on the cocked frame) until the
		// settle: a guard raised out of the strike cross-fades from this hidden pose, and the waist dragged the hand
		// through the blend (anim_test "block out of a strike"); the cocked poses sit by the guards. The strike clip
		// itself settles to the waist, so the rest is there when it ends.
		if ( _swordStrikeStarted && now < _swordStrikeAtSandbox + StrikePresentationSeconds() * StrikeRestFromShare )
			return CockedPoseFor( _swordAttackType );

		if ( IsGuardStanceShown() || !_swordCocked )
			return SwordPose.Rest;

		if ( _cockViaMid && now < _cockMidUntil )
			return SwordPose.SwapMid;

		_cockViaMid = false;
		return CockedPoseFor( _swordAttackType );
	}

	/// <summary>The guard is up on this peer (owner's held block or the host-confirmed block): sword rests left, shield raised.</summary>
	bool IsGuardStanceShown() =>
		ResolveCombat() is { IsValid: true, Enabled: true } combat && combat.IsGuardShown;

	void SetSwordPoseParam( SkinnedModelRenderer body, int pose )
	{
		if ( _appliedSwordPose == pose )
			return;

		_appliedSwordPose = pose;
		body.Set( "sword_pose", pose );
	}

	void SetSwordInterruptParam( SkinnedModelRenderer body, bool interrupt )
	{
		if ( _appliedSwordInterrupt == interrupt )
			return;

		_appliedSwordInterrupt = interrupt;
		body.Set( "b_sword_interrupt", interrupt );
	}

	void SetSwordGuardParam( SkinnedModelRenderer body, bool guard )
	{
		if ( _appliedSwordGuard == guard )
			return;

		_appliedSwordGuard = guard;
		body.Set( "b_sword_guard", guard );
	}

	/// <summary>Guard pose side: <see cref="SwingDirs"/> Left 0 / Right 1 / Up 2 are the sword_guard_dir values.</summary>
	void SetSwordGuardDirParam( SkinnedModelRenderer body, byte direction )
	{
		var dir = direction is SwingDirs.Left or SwingDirs.Right ? direction : SwingDirs.Up;
		if ( _appliedSwordGuardDir == dir )
			return;

		_appliedSwordGuardDir = dir;
		body.Set( "sword_guard_dir", (int)dir );
	}

	/// <param name="from">Clip share the draw starts at (0 = the waist carry; <see cref="WindUpStartOutOfStrike"/> out of a strike / guard).</param>
	void StartWindUp( double start, double end, float from )
	{
		_windStartAt = start;
		_windEndAt = end;
		_windFrom = Math.Clamp( from, 0f, 1f );
		_windShown = _windFrom;
	}

	/// <summary><see cref="_windFrom"/> at the press, 1 when the strike fires; never goes back (a light held into a heavy hangs cocked).</summary>
	float WindUpProgress( double now )
	{
		var span = _windEndAt - _windStartAt;
		var t = span > 1e-3 ? (float)((now - _windStartAt) / span) : 1f;
		t = _windFrom + (1f - _windFrom) * WindDrawCurve( t );
		_windShown = Math.Max( _windShown, t );
		return _windShown;
	}

	/// <summary>
	/// Time → draw along the wind-up clip: ease-out, so the weapon comes up out of the carry quickly and slows into the cocked
	/// frame, which it reaches as the strike fires (Mark 2026-11-17: "it just looks like the player is moving in slow motion
	/// for the opener windup" - the even draw spread the whole motion over the windup). Scavs use it too (EntityCombat).
	/// </summary>
	public static float WindDrawCurve( float t )
	{
		var u = 1f - Math.Clamp( t, 0f, 1f );
		return 1f - u * u;
	}

	/// <summary>The weapon class windup, for a draw whose real windup is not known yet.</summary>
	float ClassWindupSeconds()
	{
		var combat = ResolveCombat();
		var w = combat is { IsValid: true } ? combat.GetMeleeWeaponTimings().WindupSeconds : 0.55f;
		return Math.Max( 0.05f, w );
	}

	void SetSwordWindParam( SkinnedModelRenderer body, float wind )
	{
		if ( MathF.Abs( _appliedSwordWind - wind ) < 0.002f )
			return;

		_appliedSwordWind = wind;
		body.Set( "sword_wind", wind );
	}

	void SetSwordAttackParam( SkinnedModelRenderer body, int attack )
	{
		if ( _appliedSwordAttack == attack )
			return;

		_appliedSwordAttack = attack;
		body.Set( "sword_attack", attack );
	}

	/// <summary>Clear the swing state and give the body its playback rate back; the graph returns to the rest pose on its own.</summary>
	void EndMeleeSwing( string reason )
	{
		var wasActive = _swordCocked || _swordStrikeScheduled || _swordStrikeStarted;
		_swordCocked = false;
		_swordStrikeScheduled = false;
		_swordStrikeStarted = false;
		_swordStrikeAtSandbox = double.MaxValue;
		_meleeAttackAnimBusyUntilSandbox = 0;

		if ( wasActive )
			Components.Get<PlayerCombat>()?.LogMeleeAnimStopIfAny( $"end swing ({reason})" );
	}
}
